class Solution:
    def maxGcdSum(self, nums: list[int], k: int) -> int:
        import math
        n = len(nums)
        prefix = [0]*(n+1)
        for i in range(n): prefix[i+1] = prefix[i]+nums[i]
        res = 0; pairs = []
        for i in range(n):
            new_pairs = []
            for g,s in pairs:
                ng = math.gcd(g, nums[i])
                if new_pairs and new_pairs[-1][0]==ng: new_pairs[-1]=(ng,min(new_pairs[-1][1],s))
                else: new_pairs.append((ng,s))
            if new_pairs and new_pairs[-1][0]==nums[i]: new_pairs[-1]=(nums[i],min(new_pairs[-1][1],i))
            else: new_pairs.append((nums[i],i))
            pairs = new_pairs
            for g,s in pairs:
                if i-s+1>=k: res=max(res, g*(prefix[i+1]-prefix[s]))
        return res

