class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        def f(seg):
            r=0
            for m in range(1,27):
                w=m*k
                if w>len(seg): break
                freq=[0]*26
                for i in range(len(seg)):
                    freq[ord(seg[i])-97]+=1
                    if i>=w: freq[ord(seg[i-w])-97]-=1
                    if i>=w-1 and all(c==0 or c==k for c in freq): r+=1
            return r
        res=0; st=0
        for i in range(1,len(word)):
            if abs(ord(word[i])-ord(word[i-1]))>2: res+=f(word[st:i]); st=i
        return res+f(word[st:])

class Solution:
    def numberOfSequence(self, n: int, sick: list[int]) -> int:
        MOD=10**9+7; gaps=[]
        if sick[0]>0: gaps.append(sick[0])
        for i in range(1,len(sick)):
            g=sick[i]-sick[i-1]-1
            if g>0: gaps.append(g)
        if sick[-1]<n-1: gaps.append(n-1-sick[-1])
        total=sum(gaps)
        fact=[1]*(total+1)
        for i in range(1,total+1): fact[i]=fact[i-1]*i%MOD
        inv_f=[1]*(total+1); inv_f[total]=pow(fact[total],MOD-2,MOD)
        for i in range(total-1,-1,-1): inv_f[i]=inv_f[i+1]*(i+1)%MOD
        res=fact[total]
        for g in gaps: res=res*inv_f[g]%MOD
        for i in range(1,len(sick)):
            g=sick[i]-sick[i-1]-1
            if g>0: res=res*pow(2,g-1,MOD)%MOD
        return res

