            d=[[float('inf')]*n for _ in range(n)]
            for i in range(n): d[i][i]=0
            for u,v,w in roads:
                if mask>>u&1 and mask>>v&1: d[u][v]=min(d[u][v],w); d[v][u]=min(d[v][u],w)
            for k2 in range(n):
