class Solution:
    def maxFrequencyScore(self, nums: list[int], k: int) -> int:
        nums.sort(); n=len(nums)
        prefix=[0]*(n+1)
        for i in range(n): prefix[i+1]=prefix[i]+nums[i]
        def cost(l,r):
            mid=(l+r)//2
            left_cost=nums[mid]*(mid-l)-(prefix[mid]-prefix[l])
            right_cost=(prefix[r+1]-prefix[mid+1])-nums[mid]*(r-mid)
            return left_cost+right_cost
        def check(m):
            for i in range(n-m+1):
                if cost(i,i+m-1)<=k: return True
            return False
        lo,hi=1,n
        while lo<hi:
            mid2=(lo+hi+1)//2
            if check(mid2): lo=mid2
            else: hi=mid2-1
        return lo

