class Solution:
    def placedCoins(self, edges: list[list[int]], cost: list[int]) -> list[int]:
        from collections import defaultdict
        n=len(cost); adj=defaultdict(list)
        for u,v in edges: adj[u].append(v); adj[v].append(u)
        ans=[0]*n
        def dfs(u,parent):
            vals=[cost[u]]
            for v in adj[u]:
                if v!=parent:
                    child_vals=dfs(v,u)
                    vals.extend(child_vals)
            vals.sort()
            if len(vals)>=3:
                cand=max(vals[-1]*vals[-2]*vals[-3], vals[0]*vals[1]*vals[-1])
                ans[u]=max(0,cand)
            else:
                ans[u]=1 if len(vals)<3 else 0
            # Keep only top 3 and bottom 2
            if len(vals)>5: vals=vals[:2]+vals[-3:]
            return vals
        dfs(0,-1)
        return ans

