class Solution:
    def maximizeSquareArea(self, m: int, n: int, hFences: list[int], vFences: list[int]) -> int:
        MOD=10**9+7
        def gaps(fences, bound):
            pts=sorted([1]+fences+[bound])
            s=set()
            for i in range(len(pts)):
                for j in range(i+1,len(pts)):
                    s.add(pts[j]-pts[i])
            return s
        hg=gaps(hFences,m); vg=gaps(vFences,n)
        common=hg&vg
        if not common: return -1
        side=max(common)
        return (side*side)%MOD

class Solution:
    def minimumCost(self, source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
        dist=[[float('inf')]*26 for _ in range(26)]
        for i in range(26): dist[i][i]=0
        for o,c,w in zip(original,changed,cost):
            a,b=ord(o)-97,ord(c)-97
            dist[a][b]=min(dist[a][b],w)
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    dist[i][j]=min(dist[i][j],dist[i][k]+dist[k][j])
        res=0
        for s,t in zip(source,target):
            if s==t: continue
            d=dist[ord(s)-97][ord(t)-97]
            if d==float('inf'): return -1
            res+=d
        return res

class Solution:
    def minimumCost(self, source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
        # Map unique strings to indices
        idx={}; cnt=0
        for s in original+changed:
            if s not in idx: idx[s]=cnt; cnt+=1
        dist=[[float('inf')]*cnt for _ in range(cnt)]
        for i in range(cnt): dist[i][i]=0
        for o,c,w in zip(original,changed,cost):
            a,b=idx[o],idx[c]
            dist[a][b]=min(dist[a][b],w)
        for k in range(cnt):
            for i in range(cnt):
                if dist[i][k]==float('inf'): continue
                for j in range(cnt):
                    dist[i][j]=min(dist[i][j],dist[i][k]+dist[k][j])
        n=len(source)
        dp=[float('inf')]*(n+1); dp[0]=0
        # Build trie of original/changed strings for matching
        for i in range(n):
            if dp[i]==float('inf'): continue
            if source[i]==target[i]: dp[i+1]=min(dp[i+1],dp[i])
            for o in idx:
                L=len(o)
                if i+L>n: continue
                src_sub=source[i:i+L]; tgt_sub=target[i:i+L]
                if src_sub in idx and tgt_sub in idx:
                    d=dist[idx[src_sub]][idx[tgt_sub]]
                    dp[i+L]=min(dp[i+L],dp[i]+d)
        return dp[n] if dp[n]!=float('inf') else -1

