class Solution:
    def selfDivisiblePermutationCount(self, n: int) -> int:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, mask):
            if pos>n: return 1
            res=0
            for num in range(1,n+1):
                if mask>>(num-1)&1: continue
                if pos%num==0 or num%pos==0:
                    res+=dp(pos+1, mask|(1<<(num-1)))
            return res
        return dp(1,0)

