class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x<=y: return y-x
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(v):
            if v<=y: return y-v
            res=v-y  # just decrement
            res=min(res, v%5+1+dp(v//5))
            res=min(res, (5-v%5)+1+dp(v//5+1))
            res=min(res, v%11+1+dp(v//11))
            res=min(res, (11-v%11)+1+dp(v//11+1))
            return res
        return dp(x)

class Solution:
    def areaOfMaxDiagonal(self, dimensions: list[list[int]]) -> int:
        best_diag=0; best_area=0
        for l,w in dimensions:
            d=l*l+w*w  # compare squared to avoid float
            if d>best_diag or (d==best_diag and l*w>best_area):
                best_diag=d; best_area=l*w
        return best_area
